#!/usr/bin/env bash
# Generate a complete `infra/langfuse/.env` with fresh random secrets.
#
# Runs next to the compose file, so on the Docker host it is invoked as
# `bash scripts/gen-env.sh` from `infra/langfuse/`. It never overwrites an
# existing `.env`: rotating secrets against an initialized database would lock
# out the existing project.
set -euo pipefail

cd "$(dirname "$0")/.."

if [ -f .env ]; then
  echo ".env already exists at $PWD/.env; refusing to overwrite" >&2
  exit 0
fi

rand() {
  openssl rand -hex "${1:-32}"
}

umask 077
cat > .env <<EOF
# Generated by scripts/gen-env.sh. Git-ignored. Do not commit.
LANGFUSE_IMAGE_TAG=4.76.0
NEXTAUTH_URL=http://localhost:3000
NEXTAUTH_SECRET=$(rand 32)
SALT=$(rand 16)
ENCRYPTION_KEY=$(rand 32)

POSTGRES_USER=langfuse
POSTGRES_PASSWORD=$(rand 24)
POSTGRES_DB=langfuse

CLICKHOUSE_USER=langfuse
CLICKHOUSE_PASSWORD=$(rand 24)

REDIS_AUTH=$(rand 24)

MINIO_ROOT_USER=langfuse
MINIO_ROOT_PASSWORD=$(rand 24)

LANGFUSE_INIT_ORG_ID=$(rand 12)
LANGFUSE_INIT_ORG_NAME=Role-Playing
LANGFUSE_INIT_PROJECT_ID=$(rand 12)
LANGFUSE_INIT_PROJECT_NAME=role-playing-evals
LANGFUSE_INIT_PROJECT_PUBLIC_KEY=pk-lf-$(rand 16)
LANGFUSE_INIT_PROJECT_SECRET_KEY=sk-lf-$(rand 22)
LANGFUSE_INIT_USER_EMAIL=evals@example.com
LANGFUSE_INIT_USER_NAME=Evaluator
LANGFUSE_INIT_USER_PASSWORD=$(rand 16)
EOF
chmod 600 .env
echo "wrote $PWD/.env (mode 600)"
